#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string firstLine, secondLine;
    getline(cin, firstLine);
    getline(cin, secondLine);
    string replaced = secondLine;
    // Replace all underscores with spaces
    for (auto &ch : replaced) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    auto trim = [](string &s) {
        size_t start = s.find_first_not_of(' ');
        size_t end = s.find_last_not_of(' ');
        if (start == string::npos || end == string::npos) {
            s = "";
        } else {
            s = s.substr(start, end - start + 1);
        }
    };
    trim(replaced);
    string insideText;
    int insideFlag = 0;
    for (char ch : replaced) {
        if (ch == '(') {
            insideFlag = 1;
        } else if (ch == ')') {
            insideText += ' ';
            insideFlag = 0;
        } else if (insideFlag == 1) {
            insideText += ch;
        }
    }
    string s = secondLine;
    size_t pos;
    while ((pos = s.find('(')) != string::npos) {
        size_t endPos = s.find(')', pos);
        if (endPos == string::npos) break;
        s = s.substr(0, pos) + " " + s.substr(endPos + 1);
    }
    // Replace multiple spaces with a single space
    string temp;
    bool inSpace = false;
    for (char ch : s) {
        if (isspace(ch)) {
            if (!inSpace) {
                temp += ' ';
                inSpace = true;
            }
        } else {
            temp += ch;
            inSpace = false;
        }
    }
    trim(temp);
    s = temp;
    // Process insideText
    string insideStr = insideText;
    temp.clear();
    inSpace = false;
    for (char ch : insideStr) {
        if (isspace(ch)) {
            if (!inSpace) {
                temp += ' ';
                inSpace = true;
            }
        } else {
            temp += ch;
            inSpace = false;
        }
    }
    trim(temp);
    insideStr = temp;
    vector<string> outArr, inArr;
    istringstream iss(s);
    string word;
    while (iss >> word) {
        outArr.push_back(word);
    }
    istringstream iss2(insideStr);
    while (iss2 >> word) {
        inArr.push_back(word);
    }
    int maxLen = 0;
    for (const auto &w : outArr) {
        if ((int)w.length() > maxLen) {
            maxLen = w.length();
        }
    }
    if (!insideStr.empty()) {
        cout << maxLen << " " << inArr.size() << "\n";
    } else {
        cout << maxLen << " 0\n";
    }
    return 0;
}
